-- C18 marine CKH candidate evidence from K-Part interactive catalog.
-- Not a fitment approval: exact engine serial sequence and arrangement must still be verified in Cat SIS.
on conflict (evidence_key) do update set name=excluded.name,source_name=excluded.source_name,source_url=excluded.source_url,source_note=excluded.source_note,updated_at=now()
where public.kpart_catalog_evidence.review_state='CANDIDATE';